body:
Review of P04 against the proven gpu/video plug-in (n2avc_vt.c / n2vt_shim.c) and against new cache facts. ABI layout: identical to n2vt_abi.h (base 11 slots, class v1, vtable, factory signature, emit signature): no divergence. Property tolerance, 420v/420f + IOSurface attributes, one-emit-per-frame, invalidate/finalize: match n2avc. Findings:

F32 RESOLVED [V] (facts/VT_DECODER_ABI.md section 5): VTCompressionSessionCreateWithOptions RETRIES the next candidate after ANY StartSession error: on failure it invalidates+releases the instance and calls VTSelectAndCreateVideoEncoderInstanceInternal again from chosenIndex+1 (0x194cd5b20..0x194cd5c70), returning the first error only when no candidate is left. CreateInstance errors also fall through (0x194ed8200..0x194ed82ec). Encoder sort (vtSortRegistryItemsByVideoEncoderRating 0x194ed936c, result negated at 0x194ed9590): higher kVTVideoEncoder_Rating first, then hardware first, then ImplementationID descending. So -12915 at StartSession does give the software encoder when vcodecd is down.

D1 (medium, Camera stall): every client receive waits N2VCD_CLIENT_TIMEOUT_MS = 5000 ms (def_connect passes 0), inside StartSession/EncodeFrame, i.e. on Camera's capture/encode thread under e->lock. A wedged daemon = 5 s per call. Patch 1 below: connect+OPEN 2000 ms, every later request 1000 ms via n2vcd_set_timeout (exists in client/n2vcd_client.c:247).

D2 (low, diagnostics divergence): n2avc logs unknown properties ("property X kept without effect"), session start/end and failures on the console; P04 keeps unknown keys silently and has only the trace hook, which nothing installs. On the phone we would not see why the hardware path was skipped. Patch 2: weak n2vt_say (present in the product dylib via n2vt_log.c, NULL in the host suite) with the same lines as n2avc. TRACE stays as is.

D3 (registration/fallback policy, gpu/video owner): register P04 only with claim-hw. That is right for a second reason: with claim-hw, n2avc and VCPHEVC are ALSO registered as hardware, so a session that requires a hardware encoder (CMPhoto/Camera paths using RequireHardwareAcceleratedVideoEncoder) still finds the software encoder when P04's StartSession fails. Without claim-hw on the fallback, a RequireHW session with vcodecd down would fail. Patch 3 (n2vt_shim.c, not P04's file) is P04's own snippet placed after the existing registrations, plus a log line. Keep the gate until M4c; F32 no longer forces it, but StartSession can still cost up to the connect timeout.

D4 (low, check only): emit_sample sets dts = pts. Correct only if vcodecd never produces B-frames; VT clients default AllowFrameReordering=true and P04 stores but ignores it. Please confirm the daemon OPEN forces IPPP (n2avc is IPPP), or set dts from the daemon.

D5 (info): the plug-in runs in mediaserverd (n2vt_log.h says so); /dev/redwood-vcodec-client must be openable from mediaserverd's sandbox. First phone run: look for "vcodecd unreachable" from patch 2.

All three patched files compile clean for arm64-apple-ios16.0 with build_ios.sh flags (-Wall -Wextra -Werror). P04 suite NOT re-run by me (the owner applies and re-runs). hw-p04: patches 1+2 are yours; hw-ip / gpu/video owner: patch 3.

=== Patch 1: gpu/hwcodec/vt/n2hwenc_client.c ===
--- a/hwcodec/vt/n2hwenc_client.c	2026-11-11 17:27:42.019461654 +0100
+++ b/hwcodec/vt/n2hwenc_client.c	2026-11-11 17:27:52.573538348 +0100
@@ -53,6 +53,13 @@
                          int force_key) N2_WEAK;
 extern int n2vcd_close(struct n2vcd_session *s) N2_WEAK;
 extern void n2vcd_disconnect(struct n2vcd_client *c) N2_WEAK;
+extern void n2vcd_set_timeout(struct n2vcd_client *c, uint32_t timeout_ms) N2_WEAK;
+
+/* Timeouts (opus-dec3 review): the client default is 5000 ms for every receive, all spent inside VideoToolbox's
+ * StartSession/EncodeFrame (Camera's capture thread). Connect + OPEN may load the vendor firmware, so they get 2 s; every
+ * later request gets 1 s (30 frames at 30 fps), after which the session is declared fatal instead of stalling the camera. */
+#define N2HWENC_CONNECT_TIMEOUT_MS 2000u
+#define N2HWENC_FRAME_TIMEOUT_MS   1000u

 static int status_to_errno(int status)
 {
@@ -72,7 +79,7 @@
 	if (n2vcd_connect_path == NULL || n2vcd_status_errno == NULL)
 		return N2HWENC_CLIENT_ABSENT;
 	err[0] = '\0';
-	status = n2vcd_connect_path(client, socket_path, device_path, 0, err, sizeof(err));
+	status = n2vcd_connect_path(client, socket_path, device_path, N2HWENC_CONNECT_TIMEOUT_MS, err, sizeof(err));
 	if (status != 0)
 		return status_to_errno(status);
 	return 0;
@@ -106,6 +113,8 @@
 		return status_to_errno(status);
 	if (*session == NULL)
 		return -1;
+	if (n2vcd_set_timeout != NULL)
+		n2vcd_set_timeout(client, N2HWENC_FRAME_TIMEOUT_MS);
 	if (in_bytes != NULL)
 		*in_bytes = n2vcd_session_in_bytes(*session);
 	if (out_bytes != NULL)

=== Patch 2: gpu/hwcodec/vt/n2hwenc_vt.c ===
--- a/hwcodec/vt/n2hwenc_vt.c	2026-11-11 17:27:42.026461534 +0100
+++ b/hwcodec/vt/n2hwenc_vt.c	2026-11-11 17:28:16.705631472 +0100
@@ -30,6 +30,16 @@
 #define N2_CODEC_HEV1 0x68657631u   /* 'hev1' */

 #define N2HWENC_MAX_PS 8
+
+#if defined(__APPLE__) && !defined(N2_HOST_FAKE)
+#define N2_WEAK_LOG __attribute__((weak_import))
+#else
+#define N2_WEAK_LOG __attribute__((weak))
+#endif
+/* gpu/video/vt/n2vt_log.c's console channel when it is in the same dylib (the product link), absent in the host suite.
+ * Same lines as n2avc_vt.c so a phone run shows what Camera asks for and why the hardware path was skipped. */
+extern void n2vt_say(const char *format, ...) __attribute__((format(printf, 1, 2))) N2_WEAK_LOG;
+#define N2HW_SAY(...) do { if (n2vt_say != NULL) n2vt_say(__VA_ARGS__); } while (0)
 #define N2HWENC_MAX_OUT (64u * 1024u * 1024u)

 /* ------------------------------------------------------------------ trace */
@@ -695,6 +705,8 @@
 		e->session = NULL;
 		pthread_mutex_unlock(&e->lock);
 		trace(N2HWENC_TRACE_CONNECT_FAILED, (uint32_t)r, 0);
+		N2HW_SAY("n2hwenc: %s %dx%d: vcodecd unreachable (%d), VideoToolbox falls back to the next encoder",
+		         e->codec == N2HWENC_HEVC ? "hevc" : "avc", (int)dims.width, (int)dims.height, r);
 		status = N2_kVTVideoEncoderNotAvailableNowErr;
 		goto done;
 	}
@@ -705,10 +717,15 @@
 		e->conn = NULL;
 		e->session = NULL;
 		pthread_mutex_unlock(&e->lock);
+		N2HW_SAY("n2hwenc: %s %dx%d: OPEN refused (%d), VideoToolbox falls back to the next encoder",
+		         e->codec == N2HWENC_HEVC ? "hevc" : "avc", (int)dims.width, (int)dims.height, (int)status);
 		status = N2_kVTVideoEncoderNotAvailableNowErr;
 		goto done;
 	}
 	pthread_mutex_unlock(&e->lock);
+	N2HW_SAY("n2hwenc: %s %dx%d: hardware session open (bitrate %u, gop %u, profile %u level %u)",
+	         e->codec == N2HWENC_HEVC ? "hevc" : "avc", (int)dims.width, (int)dims.height, effective_bitrate(e),
+	         effective_gop(e), e->profile, e->level);

 	status = VTEncoderSessionSetPixelBufferAttributes(session, attributes);
 done:
@@ -844,6 +861,7 @@
 	(void)CVPixelBufferUnlockBaseAddress(pb, kCVPixelBufferLock_ReadOnly);
 	if (r != 0) {
 		trace(N2HWENC_TRACE_FRAME_FAILED, (uint32_t)r, 0);
+		N2HW_SAY("n2hwenc: ENC_FRAME failed (%d) after %llu pictures: session fatal", r, (unsigned long long)e->frames);
 		status = emit_failure(e, frame, N2_kVTVideoEncoderMalfunctionErr);
 		e->fatal = 1;                   /* a failed ENC_FRAME leaves the daemon session unusable */
 		pthread_mutex_unlock(&e->lock);
@@ -1014,6 +1032,11 @@
 	id = prop_find(key);
 	if (id < 0) {
 		/* A key we do not know is kept and accepted (as n2avc_vt.c does): refusing one could stop a recording. */
+		char keybuf[96];
+		if (CFStringGetCString(key, keybuf, (CFIndex)sizeof(keybuf), kCFStringEncodingUTF8))
+			N2HW_SAY("n2hwenc: property %s kept without effect", keybuf);
+		else
+			N2HW_SAY("n2hwenc: property (unprintable) kept without effect");
 		pthread_mutex_lock(&e->lock);
 		CFDictionarySetValue(e->props, key, value);
 		pthread_mutex_unlock(&e->lock);
@@ -1153,6 +1176,10 @@
 	pthread_mutex_lock(&e->lock);
 	if (!e->invalidated) {
 		trace(N2HWENC_TRACE_INVALIDATE, (uint32_t)e->frames, (uint32_t)e->bytes);
+		if (e->session != NULL || e->frames != 0)
+			N2HW_SAY("n2hwenc: session %dx%d ended: %llu pictures (%llu key), %llu bytes, %u failures", (int)e->width,
+			         (int)e->height, (unsigned long long)e->frames, (unsigned long long)e->key_frames,
+			         (unsigned long long)e->bytes, e->failures);
 		e->invalidated = 1;
 		object_teardown(e);
 	}

=== Patch 3: gpu/video/vt/n2vt_shim.c (gpu/video owner) ===
--- a/video/vt/n2vt_shim.c	2026-11-11 17:27:42.033798965 +0100
+++ b/video/vt/n2vt_shim.c	2026-11-11 17:28:36.328529533 +0100
@@ -50,6 +50,8 @@
  * Both are absent from the link until their package is there (build_ios.sh allows the two undefined names while it is not). */
 extern OSStatus n2avc_vt_create(uint32_t codecType, CFAllocatorRef allocator, VTVideoEncoderRef *instanceOut) N2_WEAK;
 extern OSStatus n2jpeg_vt_create(uint32_t codecType, CFAllocatorRef allocator, VTVideoEncoderRef *instanceOut) N2_WEAK;
+/* P04's hardware encoders (gpu/hwcodec/vt/n2hwenc_register.c): avc1/hvc1/hev1, IsHardwareAccelerated, Rating 100. */
+extern int n2hwenc_register_all(void) N2_WEAK;

 /* VideoToolbox and the CoreFoundation calls used below, as weak imports (see the file comment). */
 extern OSStatus VTRegisterVideoEncoderWithInfo(uint32_t codecType, CFDictionaryRef info,
@@ -194,6 +196,16 @@

 	n2vt_say("registered: hvc1=%s hev1=%s avc1=%s jpeg=%s",
 	         state[N2_HEVC_HVC1], state[N2_HEVC_HEV1], state[N2_AVC1], state[N2_JPEG]);
+
+	/* Hardware encoders (P04), only together with claim-hw: then the software encoders above are registered as hardware
+	 * too, so a session that requires a hardware encoder (Camera/CMPhoto) still finds n2avc / VCPHEVC when the VENC path
+	 * fails. Order is decided by VideoToolbox, not by registration order: Rating 100 sorts first, and a StartSession error
+	 * (vcodecd unreachable: -12915) makes VTCompressionSessionCreate retry the next candidate [V 0x194cd5b20..0x194cd5c70,
+	 * gpu/hwcodec/facts/VT_DECODER_ABI.md section 5]. */
+	if (n2hwenc_register_all != NULL && claim_hw)
+		n2vt_say("hardware encoders registered: %d", n2hwenc_register_all());
+	else
+		n2vt_say("hardware encoders: %s", n2hwenc_register_all == NULL ? "absent" : "off (no claim-hw)");
 }

 __attribute__((visibility("default"))) void
